def backfill_lines(apps, schema_editor):
    rental = apps.get_model("catalog", "Rental")
    line = apps.get_model("catalog", "RentalLine")
    database = schema_editor.connection.alias
    rows = (
        rental.objects.using(database)
        .order_by("pk")
        .values_list("pk", "equipment_id", "quantity", "daily_rate_vnd", "total_vnd")
        .iterator(chunk_size=1000)
    )
    while batch := list(islice(rows, 1000)):
        line.objects.using(database).bulk_create(
            [
                line(
                    rental_id=pk,
                    equipment_id=equipment,
                    quantity=quantity,
                    daily_rate_vnd=rate,
                    total_vnd=total,
                )
                for pk, equipment, quantity, rate, total in batch
            ]
        )


def prevent_data_loss_on_reverse(apps, schema_editor):
    database = schema_editor.connection.alias
    asset = apps.get_model("catalog", "AssetUnit")
    equipment = apps.get_model("catalog", "Equipment")
    rental = apps.get_model("catalog", "Rental")
    if (
        asset.objects.using(database).exists()
        or equipment.objects.using(database).filter(tracks_assets=True).exists()
        or rental.objects.using(database).filter(equipment__isnull=True).exists()
    ):
        raise IrreversibleError(
            "Cannot remove asset tracking or multi-line orders. Restore a verified backup."
        )


